    <div class="form-grid"><label>Shift title<input name="title" required placeholder="e.g. Routine inspections — Docklands"></label><label>Shift type<select name="shift_type"><option value="property_management">Property management</option><option value="inspection">Inspection / viewing</option><option value="open_home">Open home</option><option value="leasing">Leasing</option><option value="maintenance">Maintenance</option><option value="cleaning">Cleaning / turnover</option><option value="compliance">Compliance</option><option value="office">Office coverage</option><option value="on_call">On-call</option><option value="emergency">Emergency response</option></select></label></div>
    <div class="form-grid"><label>{{ $verticalTerms['workerSingular'] }}<select name="worker_public_id" id="shiftWorker"><option value="">Leave unassigned</option></select></label><label>{{ $verticalTerms['premisesSingular'] }}<select name="premises_public_id" id="shiftPremises"><option value="">No single {{ strtolower($verticalTerms['premisesSingular']) }}</option></select></label></div>
    <div class="form-grid"><label>Starts<input type="datetime-local" name="starts_at" required></label><label>Ends<input type="datetime-local" name="ends_at" required></label></div>
    <div class="form-grid"><label>Workers required<input type="number" name="required_worker_count" min="1" max="100" value="1"></label><label>Timezone<input name="timezone" value="{{ $timezone }}" required></label></div>
