    <div class="form-grid"><label>{{ $verticalTerms['workerSingular'] }}<select name="worker_public_id" id="availabilityWorker" required></select></label><label>Availability type<select name="availability_type"><option value="available">Available</option><option value="preferred">Preferred</option><option value="on_call">On-call</option><option value="unavailable">Unavailable</option></select></label></div>
    <div class="form-grid three"><label>Weekday<select name="weekday"><option value="1">Monday</option><option value="2">Tuesday</option><option value="3">Wednesday</option><option value="4">Thursday</option><option value="5">Friday</option><option value="6">Saturday</option><option value="7">Sunday</option></select></label><label>From<input type="time" name="starts_at" value="09:00" required></label><label>Until<input type="time" name="ends_at" value="17:00" required></label></div>
    <div class="notice">Availability is checked against roster shifts, Appointments and Dispatch assignments. Managers can override conflicts only with an auditable reason.</div>
