<div class="toast" id="toast"></div>
<script>
const apiPrefix = '/' + @json($apiPrefix).replace(/^\/+|\/+$/g,'');
const csrf = document.querySelector('meta[name="csrf-token"]').content;
const verticalTerms = @json($verticalTerms);
const state = {rosters:[], roster:null, workers:[], premises:[], availability:[], view:'roster'};
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const requestId = () => (crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`);
async function api(path, options={}){
    const write = options.method && options.method !== 'GET';
    const headers = {'Accept':'application/json',...(write?{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Idempotency-Key':requestId(),'X-WorkCore-Confirmation':requestId()}:{}),...(options.headers||{})};
    const response = await fetch(`${apiPrefix}${path}`, {...options, headers});
    const body = await response.json().catch(()=>({}));
    if(!response.ok){throw new Error(body?.errors?.[0]?.detail || body?.message || `Request failed (${response.status})`)}
    return body.data;
}
function attrs(resource){return resource?.attributes ? {id:resource.id,...resource.attributes} : (resource?.public_id ? {id:resource.public_id,...resource} : resource)}
function toast(message,error=false){const t=$('toast');t.textContent=message;t.className=`toast show ${error?'error':''}`;setTimeout(()=>t.className='toast',2800)}
function initials(name){return String(name||'?').split(/\s+/).map(v=>v[0]).join('').slice(0,2).toUpperCase()}
function hoursBetween(start,end){return Math.max(0,(new Date(end)-new Date(start))/3600000)}
function localDay(date){return new Date(date).toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'})}
function dayKey(date){const d=new Date(date);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekDays(){if(!state.roster)return[];const start=new Date(`${state.roster.starts_on}T00:00:00`);return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d})}
function populateSelectors(){
    $('rosterSelect').innerHTML='<option value="">Select a roster</option>'+state.rosters.map(r=>`<option value="${r.id}" ${state.roster?.id===r.id?'selected':''}>${esc(r.name)} · ${esc(r.starts_on)}</option>`).join('');
    const workerOptions=state.workers.map(w=>`<option value="${w.id}">${esc(w.display_name)} — ${esc(w.job_title||w.worker_type)}</option>`).join('');
    $('workerFilter').innerHTML=`<option value="">All ${esc(verticalTerms.workerPlural.toLowerCase())}</option>`+workerOptions;$('shiftWorker').innerHTML='<option value="">Leave unassigned</option>'+workerOptions;$('availabilityWorker').innerHTML=workerOptions;
    const premiseOptions=state.premises.map(p=>`<option value="${p.id}">${esc(p.name)}${p.suburb?' — '+esc(p.suburb):''}</option>`).join('');
    $('premisesFilter').innerHTML=`<option value="">All ${esc(verticalTerms.premisesPlural.toLowerCase())}</option>`+premiseOptions;$('shiftPremises').innerHTML=`<option value="">No single ${esc(verticalTerms.premisesSingular.toLowerCase())}</option>`+premiseOptions;$('rosterPremises').innerHTML=`<option value="">Across multiple ${esc(verticalTerms.premisesPlural.toLowerCase())}</option>`+premiseOptions;
}
function filteredWorkers(){const id=$('workerFilter').value;return state.workers.filter(w=>!id||w.id===id)}
function filteredShifts(){if(!state.roster)return[];const premise=$('premisesFilter').value;return (state.roster.shifts||[]).filter(s=>!premise||s.premises_public_id===premise)}
function updateMetrics(){const shifts=filteredShifts();const assignments=shifts.flatMap(s=>s.assignments||[]);const workerIds=new Set(assignments.map(a=>a.worker_public_id));const siteDays=new Set(shifts.filter(s=>s.premises_public_id).map(s=>`${s.premises_public_id}:${dayKey(s.starts_at)}`));const hours=shifts.reduce((sum,s)=>sum+hoursBetween(s.starts_at,s.ends_at)*Math.max(1,(s.assignments||[]).length),0);const gaps=shifts.reduce((sum,s)=>sum+Math.max(0,Number(s.required_worker_count||1)-(s.assignments||[]).filter(a=>['assigned','accepted'].includes(a.status)).length),0);$('hoursMetric').textContent=hours.toFixed(1);$('workersMetric').textContent=workerIds.size;$('sitesMetric').textContent=siteDays.size;$('gapsMetric').textContent=gaps;$('coverageSide').textContent=`${siteDays.size} site-days`;}
function render(){populateSelectors();updateMetrics();if(state.view==='availability')renderAvailability();else renderRoster()}
function renderRoster(){const panel=$('panel');if(!state.roster){panel.innerHTML='<div class="empty"><div><h3>Create or select a roster</h3><p>Plan weekly coverage for property managers, rooming-house staff, agents, inspectors, cleaners, technicians and contractors.</p></div></div>';return}const days=weekDays();const shifts=filteredShifts();const workers=filteredWorkers();panel.innerHTML=`<div class="panel-head"><div><h2>${esc(state.roster.name)}</h2><p>${esc(state.roster.roster_type.replaceAll('_',' '))} · ${esc(state.roster.starts_on)} to ${esc(state.roster.ends_on)}</p></div><div><span class="status ${esc(state.roster.status)}">${esc(state.roster.status)}</span> ${state.roster.status==='draft'?'<button class="btn primary" id="publishBtn">Publish roster</button>':''}</div></div><div class="roster-wrap"><div class="grid"><div class="grid-head"><div>${esc(verticalTerms.workerSingular)}</div>${days.map(d=>`<div class="day"><strong>${d.toLocaleDateString('en-AU',{weekday:'short'})}</strong><span>${d.toLocaleDateString('en-AU',{day:'numeric',month:'short'})}</span></div>`).join('')}</div>${workers.map(w=>`<div class="worker-row"><div class="worker"><div class="avatar">${initials(w.display_name)}</div><div><strong>${esc(w.display_name)}</strong><span>${esc(w.job_title||w.worker_type)}</span><small>${esc(w.worker_type)}</small></div></div>${days.map(day=>{const key=dayKey(day);const availability=state.availability.filter(a=>a.worker_public_id===w.id&&Number(a.weekday)===((day.getDay()+6)%7+1));const workerShifts=shifts.filter(s=>dayKey(s.starts_at)===key&&(s.assignments||[]).some(a=>a.worker_public_id===w.id));return `<div class="cell"><div class="availability">${availability.length?availability.map(a=>`${a.starts_at?.slice(0,5)||'all day'}–${a.ends_at?.slice(0,5)||''}`).join(', '):'No availability rule'}</div>${workerShifts.map(s=>`<button class="shift ${esc(s.shift_type)}" title="${esc(s.instructions||'')}"><span>${new Date(s.starts_at).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})}–${new Date(s.ends_at).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})}</span><strong>${esc(s.title)}</strong><small>${esc(s.premises_name||'Portfolio / remote')}</small></button>`).join('')}</div>`}).join('')}</div>`).join('')}</div></div>`;$('publishBtn')?.addEventListener('click',publishRoster)}
function renderAvailability(){const panel=$('panel');const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];panel.innerHTML=`<div class="panel-head"><div><h2>Declared ${esc(verticalTerms.workerSingular.toLowerCase())} availability</h2><p>Recurring operational availability used by Scheduling, Dispatch and roster conflict checks.</p></div><button class="btn primary" id="availabilityAdd">+ Add rule</button></div><div class="availability-table"><div class="availability-head"><div>${esc(verticalTerms.workerSingular)}</div>${days.map(d=>`<div>${d}</div>`).join('')}</div>${filteredWorkers().map(w=>`<div class="availability-row"><div class="worker"><div class="avatar">${initials(w.display_name)}</div><div><strong>${esc(w.display_name)}</strong><span>${esc(w.job_title||w.worker_type)}</span></div></div>${days.map((_,i)=>{const rules=state.availability.filter(a=>a.worker_public_id===w.id&&Number(a.weekday)===i+1);if(!rules.length)return '<button class="availability-cell">Set hours</button>';const primary=rules[0];return `<button class="availability-cell ${esc(primary.availability_type)}">${esc(primary.availability_type.replace('_',' '))}<br>${esc((primary.starts_at||'').slice(0,5))}–${esc((primary.ends_at||'').slice(0,5))}</button>`}).join('')}</div>`).join('')}</div>`;$('availabilityAdd').onclick=()=>openDialog('availabilityDialog')}
async function loadRoster(id){if(!id){state.roster=null;render();return}const data=await api(`/rosters/${id}`);state.roster=attrs(data);render()}
async function loadAll(){try{const [rosters,workers,premises,availability]=await Promise.all([api('/rosters?per_page=100'),api('/workers?per_page=100'),api('/premises?per_page=100'),api('/availability?per_page=100')]);state.rosters=rosters.map(attrs);state.workers=workers.map(attrs);state.premises=premises.map(attrs);state.availability=availability.map(attrs);if(state.rosters[0])await loadRoster(state.rosters[0].id);else render()}catch(error){$('panel').innerHTML=`<div class="empty"><div><h3>Roster API is not available</h3><p>${esc(error.message)}. Enable WorkCore roster routes in the complete MagicAI host.</p></div></div>`;toast(error.message,true)}}
function openDialog(id){$(id).showModal()}document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>button.closest('dialog').close());
$('rosterSelect').onchange=e=>loadRoster(e.target.value);$('workerFilter').onchange=render;$('premisesFilter').onchange=render;$('newRosterBtn').onclick=()=>openDialog('rosterDialog');$('newShiftBtn').onclick=()=>state.roster?openDialog('shiftDialog'):toast('Create or select a roster first',true);$('availabilityBtn').onclick=()=>openDialog('availabilityDialog');document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{state.view=button.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===button));render()});
$('rosterForm').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target).entries());if(!data.premises_public_id)delete data.premises_public_id;try{const result=await api('/rosters',{method:'POST',body:JSON.stringify(data)});event.target.closest('dialog').close();event.target.reset();state.rosters.unshift(attrs(result));await loadRoster(attrs(result).id);toast('Roster created')}catch(error){toast(error.message,true)}};
$('shiftForm').onsubmit=async event=>{event.preventDefault();const fd=new FormData(event.target);const data=Object.fromEntries(fd.entries());data.roster_public_id=state.roster.id;data.required_worker_count=Number(data.required_worker_count||1);data.allow_conflicts=fd.has('allow_conflicts');for(const key of ['worker_public_id','premises_public_id','conflict_override_reason'])if(!data[key])delete data[key];try{await api('/roster-shifts',{method:'POST',body:JSON.stringify(data)});event.target.closest('dialog').close();event.target.reset();await loadRoster(state.roster.id);toast('Roster shift created')}catch(error){toast(error.message,true)}};
$('availabilityForm').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target).entries());data.weekday=Number(data.weekday);data.recurrence_type='weekly';data.timezone=@json($timezone);try{await api('/availability',{method:'POST',body:JSON.stringify(data)});event.target.closest('dialog').close();const availability=await api('/availability?per_page=100');state.availability=availability.map(attrs);render();toast('Availability saved')}catch(error){toast(error.message,true)}};
async function publishRoster(){try{await api(`/rosters/${state.roster.id}/publish`,{method:'POST',body:JSON.stringify({status:'published'})});await loadRoster(state.roster.id);toast('Roster published')}catch(error){if(error.message.includes('uncovered')){const reason=prompt('This roster has coverage gaps. Enter an audit reason to publish deliberately:');if(reason){await api(`/rosters/${state.roster.id}/publish`,{method:'POST',body:JSON.stringify({status:'published',allow_gaps:true,reason})});await loadRoster(state.roster.id);toast('Roster published with recorded coverage gaps')}}else toast(error.message,true)}}
loadAll();
</script>
</body>
</html>
